    "enabled": true,
    "tag_map": {
      "@cheap": "cheap",
      "@default": "default",
      "@pro": "pro",
      "@ultra": "ultra"
    },
    "commands": {
      "router status": "status",
      "router auto on": "auto_on",
      "router auto off": "auto_off"
